/**
 * Opens the bundled, pre-built library database.
 *
 * On first launch — or whenever the bundled DB_VERSION differs from the copy on
 * the device — assets/db/library.db is copied into the SQLite directory
 * (overwriting any stale copy) and then opened. The version lives both in
 * assets/db/db-version.json (generated by scripts/build-db.js) and in the DB's
 * own `meta` table, so a half-copied or foreign file is detected and replaced.
 */
import AsyncStorage from '@react-native-async-storage/async-storage';
import { importDatabaseFromAssetAsync, openDatabaseAsync, type SQLiteDatabase } from 'expo-sqlite';

import type { QueryAdapter } from '../../shared/quickJump';
import dbVersion from '../../assets/db/db-version.json';

export const DB_NAME = 'library.db';
export const DB_VERSION: string = dbVersion.version;
const DB_VERSION_KEY = 'kodeshread.dbVersion';

const DB_ASSET = require('../../assets/db/library.db');

async function readInstalledVersion(db: SQLiteDatabase): Promise<string | null> {
  try {
    const row = await db.getFirstAsync<{ value: string }>("SELECT value FROM meta WHERE key = 'db_version'");
    return row?.value ?? null;
  } catch {
    return null; // empty/new file: no meta table
  }
}

async function copyFromAsset(): Promise<void> {
  await importDatabaseFromAssetAsync(DB_NAME, { assetId: DB_ASSET, forceOverwrite: true });
}

export async function openLibraryDatabase(): Promise<SQLiteDatabase> {
  const stored = await AsyncStorage.getItem(DB_VERSION_KEY).catch(() => null);
  if (stored !== DB_VERSION) await copyFromAsset();

  let db = await openDatabaseAsync(DB_NAME);
  let installed = await readInstalledVersion(db);
  if (installed !== DB_VERSION) {
    // Stored flag was stale (e.g. app data partially cleared): copy again.
    await db.closeAsync();
    await copyFromAsset();
    db = await openDatabaseAsync(DB_NAME);
    installed = await readInstalledVersion(db);
    if (installed !== DB_VERSION) {
      throw new Error(`Library DB version mismatch after copy (bundled ${DB_VERSION}, found ${installed ?? 'none'})`);
    }
  }
  await AsyncStorage.setItem(DB_VERSION_KEY, DB_VERSION).catch(() => undefined);
  // The library is read-only at runtime.
  await db.execAsync('PRAGMA query_only = ON; PRAGMA temp_store = MEMORY;');
  return db;
}

/** Adapter used by the shared (platform-independent) query modules. */
export function toAdapter(db: SQLiteDatabase): QueryAdapter {
  return {
    all: <T,>(sql: string, params: (string | number | null)[]) => db.getAllAsync<T>(sql, params),
  };
}
